const root='.local/smart-takes-2026-10-29/'; const frames=JSON.parse(readFileSync(root+'audio-evidence.json'))[0].frames;const offset=frames[0].start;const duration=frames.at(-1).end-offset;const p=JSON.parse(readFileSync(root+'project-before.json'));const words=p.scenes[0].takeAssembly.sourceWords.map((w,wordIndex)=>({wordIndex,start:w.start/120000-offset,end:w.end/120000-offset}));
const out=glue.analyzeSmartAudioSilence({frames:frames.map(f=>({...f,start:f.start-offset,end:f.end-offset})),durationSeconds:duration,transcriptWords:words,settings:{minSilenceSeconds:0.3,speechPaddingSeconds:0.08,bridgeGapSeconds:0.12}});console.log(JSON.stringify({diagnostics:out.diagnostics,ranges:out.cutRanges.slice(0,15)}));
